CREATE VIEW Q_LIST_FCT2 AS  SELECT        dbo.HEAD_LST.NUMBER, dbo.CUST_HESAB.NAME, SUM(dbo.INVO_LST.MABL_K + dbo.INVO_LST.IMBAA) AS SumOfMABL_K, dbo.HEAD_LST.DATE_N,dbo.HEAD_LST.TAG, COUNT(dbo.INVO_LST.CODE) AS AGHLAM, dbo.CUST_HESAB.hes, dbo.HEAD_LST.DEPATMAN, dbo.HEAD_LST.SHIFT, dbo.HEAD_LST.CUST_KIND, dbo.HEAD_LST.USER_NAME, SUM(dbo.INVO_LST.N_MOIN) AS TAKHFIF, SUM(dbo.INVO_LST.IMBAA) AS ARZESH, dbo.CUST_HESAB.ROUTE_NAME , dbo.CUST_HESAB.ADDRESS, dbo.CUST_HESAB.TEL FROM            dbo.HEAD_LST INNER JOIN dbo.INVO_LST ON dbo.HEAD_LST.TAG = dbo.INVO_LST.TAG AND dbo.HEAD_LST.NUMBER = dbo.INVO_LST.NUMBER INNER JOIN dbo.CUST_HESAB ON dbo.HEAD_LST.CUST_NO = dbo.CUST_HESAB.hes WHERE        (dbo.HEAD_LST.TAG = 2) OR (dbo.HEAD_LST.TAG = 14) GROUP BY dbo.HEAD_LST.NUMBER, dbo.CUST_HESAB.NAME, dbo.HEAD_LST.DATE_N, dbo.HEAD_LST.TAG, dbo.CUST_HESAB.hes, dbo.HEAD_LST.DEPATMAN,  dbo.HEAD_LST.SHIFT, dbo.HEAD_LST.CUST_KIND, dbo.HEAD_LST.USER_NAME, dbo.CUST_HESAB.ROUTE_NAME, dbo.CUST_HESAB.ADDRESS,dbo.CUST_HESAB.TEL
